def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

If extract_spec_version is True then will look at the type value to determine
the specification version. In the case that there is no type value or it isn't
valid, then other tests will be based on the version given in self.spec_version.
    """
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory

    # Check basic structure - required fields
    if not isinstance(inventory, dict):
        self.error('E036a')
        return

    # Check for required fields
    if 'id' not in inventory:
        self.error('E036b')
    if 'type' not in inventory:
        self.error('E036c')
    if 'digestAlgorithm' not in inventory:
        self.error('E036d')

    # Validate id field
    if 'id' in inventory:
        self.id = inventory['id']
        if not isinstance(self.id, str):
            self.error('E037a')
        else:
            # Check if it looks like a URI (has scheme:rest format)
            if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', self.id):
                self.warning('W005')

    # Validate type field and extract spec version if requested
    if 'type' in inventory:
        inv_type = inventory['type']
        if not isinstance(inv_type, str):
            if extract_spec_version:
                self.error('E038b')
            else:
                self.error('E038a')
        else:
            # Check if it's a valid OCFL type URI
            type_match = re.match(r'^https://ocfl\.io/(\d+\.\d+)/spec/#inventory$', inv_type)
            if type_match:
                if extract_spec_version:
                    extracted_version = type_match.group(1)
                    if extracted_version in self.spec_versions_supported:
                        self.spec_version = extracted_version
                    else:
                        self.error('E038c')
            else:
                if extract_spec_version:
                    self.error('E038c')
                else:
                    self.error('E038a')

    # Validate digestAlgorithm
    if 'digestAlgorithm' in inventory:
        self.digest_algorithm = inventory['digestAlgorithm']
        if not isinstance(self.digest_algorithm, str):
            self.error('E039')
        elif not self.lax_digests:
            # Check if it's a supported digest algorithm
            try:
                digest_regex(self.digest_algorithm)
            except ValueError:
                self.error('E039')

    # Validate contentDirectory
    if 'contentDirectory' in inventory:
        self.content_directory = inventory['contentDirectory']
        if not isinstance(self.content_directory, str):
            self.error('E017')
        else:
            # Check for invalid paths
            if self.content_directory in ('..', '.') or self.content_directory.startswith('../') or '/../' in self.content_directory:
                self.error('E018')

    # Validate manifest
    if 'manifest' in inventory:
        (manifest_files, unnormalized_digests, _) = self.validate_manifest(inventory['manifest'])
        self.manifest_files = manifest_files
        self.unnormalized_digests = unnormalized_digests
    else:
        self.manifest_files = {}
        self.unnormalized_digests = set()

    # Validate versions
    if 'versions' in inventory:
        all_versions = self.validate_versions(inventory['versions'], [], self.unnormalized_digests)
        self.all_versions = all_versions

        # Validate version sequence
        self.validate_version_sequence(inventory['versions'])

        # Check that content paths map to versions
        if self.manifest_files:
            self.check_content_paths_map_to_versions(self.manifest_files, all_versions)
    else:
        self.all_versions = []

    # Validate head
    if 'head' in inventory:
        self.head = inventory['head']
        if not isinstance(self.head, str):
            self.error('E040')
        elif self.all_versions and self.head not in self.all_versions:
            self.error('E040')

    # Validate fixity if present
    if 'fixity' in inventory and self.manifest_files:
        self.validate_fixity(inventory['fixity'], self.manifest_files)

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

Check the structure of the fixity block and makes sure that only files
listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        self.error('E056a')
        return
    for algorithm in fixity:
        if not self.lax_digests and algorithm not in self.digest_algorithm:
            self.error('E056b', algorithm=algorithm)
            continue
        if not isinstance(fixity[algorithm], dict):
            self.error('E057a', algorithm=algorithm)
            continue
        seen_digests = set()
        for digest in fixity[algorithm]:
            # Check digest format
            if not self.lax_digests:
                m = re.match(self.digest_regex(), digest)
                if not m:
                    self.error('E057b', algorithm=algorithm, digest=digest)
                    continue
            # Check value is a list
            if not isinstance(fixity[algorithm][digest], list):
                self.error('E057c', algorithm=algorithm, digest=digest)
                continue
            # Check for duplicate normalized digests
            norm_digest = normalized_digest(digest, digest_type=algorithm)
            if norm_digest in seen_digests:
                self.error('E097', digest=norm_digest)
            else:
                seen_digests.add(norm_digest)
            # Check files are in manifest
            for file in fixity[algorithm][digest]:
                if manifest_files is not None and file not in manifest_files:
                    self.error('E057d', file=file)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

Also keep a record of any content digests different from those in the root inventory
so that we can also check them when validating the content.

version_dirs is an array of version directory names and is assumed to be in
version sequence (1, 2, 3...).
    """
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}

    # Track all digests seen so far
    seen_manifest_digests = set()
    seen_fixity_digests = {}  # {algorithm: set(digests)}

    for version_dir in version_dirs:
        inv_path = version_dir + '/inventory.json'

        if not self.obj_fs.exists(inv_path):
            self.log.error('E043', version=version_dir)
            continue

        try:
            inventory, inv_validator = self.validate_inventory(
                inv_path,
                where=version_dir,
                extract_spec_version=False
            )
        except ValidatorAbortException:
            continue

        # Check head matches directory
        if inv_validator.head != version_dir:
            self.log.error('E045', version=version_dir, head=inv_validator.head)

        # Check id matches root
        if inv_validator.id != self.id:
            self.log.error('E046', version=version_dir, id=inv_validator.id)

        # Check digest algorithm matches
        if inv_validator.digest_algorithm != self.digest_algorithm:
            self.log.error('E047', version=version_dir,
                          algorithm=inv_validator.digest_algorithm)

        # Validate inventory digest file
        self.validate_inventory_digest(inv_path, self.digest_algorithm, where=version_dir)

        # Collect manifest digests
        version_manifest = getattr(inv_validator, 'manifest', {}) or {}
        version_fixity = getattr(inv_validator, 'fixity', {}) or {}

        # Record new manifest digests not seen in prior versions
        for digest, paths in version_manifest.items():
            if digest not in seen_manifest_digests:
                if version_dir not in prior_manifest_digests:
                    prior_manifest_digests[version_dir] = {}
                prior_manifest_digests[version_dir][digest] = paths
                seen_manifest_digests.add(digest)

        # Record new fixity digests not seen in prior versions
        for algorithm, digest_map in version_fixity.items():
            if algorithm not in seen_fixity_digests:
                seen_fixity_digests[algorithm] = set()
            for digest, paths in digest_map.items():
                if digest not in seen_fixity_digests[algorithm]:
                    if version_dir not in prior_fixity_digests:
                        prior_fixity_digests[version_dir] = {}
                    if algorithm not in prior_fixity_digests[version_dir]:
                        prior_fixity_digests[version_dir][algorithm] = {}
                    prior_fixity_digests[version_dir][algorithm][digest] = paths
                    seen_fixity_digests[algorithm].add(digest)

    return (prior_manifest_digests, prior_fixity_digests)

