def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

>>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
{'a': 6, 'b': 2}
    """
    """
    Combine values of the dictionaries supplied by iterable dicts.

>>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
{'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def unquote(name):
    """
    Remove quote from the given name.
    """
    """
    Remove quote from the given name.
    """
    if not name:
        return name

    # Determine if input is bytes or str
    is_bytes = isinstance(name, bytes)

    # Convert to str for regex processing if needed
    if is_bytes:
        name_str = name.decode('latin1')
    else:
        name_str = name

    # Replace ;XXX patterns with corresponding characters
    # Pattern matches ; followed by exactly 3 digits
    pattern = re.compile(r';(\d{3})')

    def replace_match(match):
        try:
            byte_val = int(match.group(1))
            if 0 <= byte_val <= 255:
                return chr(byte_val)
            else:
                return match.group(0)  # Return original if out of range
        except ValueError:
            return match.group(0)  # Return original if not a valid number

    result = pattern.sub(replace_match, name_str)

    # Convert back to bytes if input was bytes
    if is_bytes:
        return result.encode('latin1')
    else:
        return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

:return: True if gitbash
    """
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if platform.system() != "Windows":
            return False
        # Check if running under MSYS/Git Bash environment
        if "MSYSTEM" in os.environ:
            return True
        # Check parent process name
        parent_name = psutil.Process(os.getppid()).name()
        return parent_name in ("bash.exe", "sh.exe")
    except Exception:
        return False

