def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

:param args: the collected list of args.
:return: (dict, dict): flat dicts (control_args, nested_args)
    """
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    nested_args = {}
    control_args = {}
    custom_args = {}

    # Build mapping of arg dest to action spec
    arg_specs = {}
    for action in self.parser._actions:
        if action.dest and action.dest != 'help':
            arg_specs[action.dest] = action

    for arg_name, arg_value in args.items():
        arg_spec = arg_specs.get(arg_name)

        # Determine argument type properties
        is_nested = True
        is_custom = False

        if arg_spec is not None:
            arg_type = getattr(arg_spec, 'type', None)

            # Check if this is a custom args type (AdditionalOptionsType)
            if arg_type is not None and hasattr(arg_type, 'is_nested'):
                if not arg_type.is_nested:
                    # Non-nested complex types are custom args
                    if hasattr(arg_type, 'resolve'):
                        is_custom = True
                    else:
                        is_nested = False
            elif arg_type is not None and arg_type in COMPLEX_TYPES:
                is_custom = True

        if is_custom:
            # Custom args are additional ansible variables
            if arg_value:
                if isinstance(arg_value, dict):
                    custom_args.update(arg_value)
                elif isinstance(arg_value, list):
                    # Parse list of --key value pairs into dict
                    i = 0
                    while i < len(arg_value):
                        item = arg_value[i]
                        if isinstance(item, str) and item.startswith('--'):
                            key = item[2:]
                            if i + 1 < len(arg_value):
                                custom_args[key] = arg_value[i + 1]
                                i += 2
                                continue
                        i += 1
        elif is_nested:
            nested_args[arg_name] = arg_value
        else:
            control_args[arg_name] = arg_value

    return nested_args, control_args, custom_args

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.

:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
    """
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser_specs = self.spec_helper.get_parser_option_specs(parser_name)
    if not parser_specs:
        return

    def _convert(value, arg_type):
        if value is None or not isinstance(value, str):
            return value
        if arg_type is None or arg_type is str:
            return value
        try:
            if arg_type is int:
                return int(value)
            if arg_type is float:
                return float(value)
            if arg_type is bool:
                return value.lower() in ('true', 'yes', '1', 'on')
            if callable(arg_type):
                return arg_type(value)
        except (ValueError, TypeError):
            return value
        return value

    for arg_name, arg_value in values_dict.items():
        if arg_name not in parser_specs:
            continue

        option_spec = parser_specs[arg_name]
        arg_type = option_spec.get('type')
        action = option_spec.get('action', '')

        # Skip complex types - resolved later by resolve_custom_types
        if arg_type in COMPLEX_TYPES:
            continue

        # Handle boolean flags
        if action in ('store_true', 'store_false'):
            if isinstance(arg_value, str):
                values_dict[arg_name] = arg_value.lower() in (
                    'true', 'yes', '1', 'on')
            continue

        # Handle list types
        if isinstance(arg_value, list):
            values_dict[arg_name] = [
                _convert(item, arg_type) for item in arg_value]
            continue

        # Handle single value
        values_dict[arg_name] = _convert(arg_value, arg_type)

